// README / per-UUID hero SVGs — hex-only movieCanvasHex palette, SMIL-only, GitHub-safe (no script /
// foreignObject / external refs). README hero = proof composition over THEOREM_ATOM_SEED; per-UUID heroes
// remain parametric for OG cards.
const SVG_CHROMA = 9 / 64

function heroSvgPaletteFromUuid(uuid: string) {
  const hex = (uuid + uuid).replace(/[^0-9a-f]/gi, '') || '8080808080808080'
  const byte = (k: number) => parseInt(hex.slice((k * 2) % (7 * 4), ((k * 2) % (7 * 4)) + 2), 16) || (64 * 2)
  const seedHue = A432_HUE
  return {
    accent: scaleColor(byte((7 * 2)), { seedHue, dark: true, L: 7 / 8, C: SVG_CHROMA }),
    bgInner: scaleColor(byte((5 * 2)), { seedHue, dark: true, L: 11 / (16 * 2), C: SVG_CHROMA * (3 / 4) }),
    bgOuter: scaleColor(byte(11), { seedHue, dark: true, L: 3 / (16 * 2), C: SVG_CHROMA * (1 / 2) }),
    title: scaleColor(byte((6 * 2)), { seedHue, dark: true, L: 1 - 3 / 16, C: SVG_CHROMA * (1 / 4) }),
    torusMid: scaleColor(byte((5 * 3)), { seedHue, dark: true, L: 7 / 8, C: SVG_CHROMA }) }
}

/** The stillness channel for SMIL hosts — strips every self-closed animate/animateTransform element. */
export function stillSvg(svg: string): string {
  return svg.replace(/<animate[^>]*\/>/g, '').replace(/<animateTransform[^>]*\/>/g, '')
}

/** Per-UUID parametric hero (OG cards / forge chain). */
export function heroSvgFromUuid(uuid: string, opts: { animate?: boolean } = {}): string {
  const hex = (uuid + uuid).replace(/[^0-9a-f]/gi, '') || '8080808080808080'
  const byte = (k: number) => parseInt(hex.slice((k * 2) % (7 * 4), ((k * 2) % (7 * 4)) + 2), 16) || (64 * 2)
  const colors = heroSvgPaletteFromUuid(uuid)
  const W = 760, H = (64 * 6), cx = W / 2, cy = 176
  const G0 = round(byte((6 * 2)) * 360 / (64 * 4)), G1 = round(byte(13) * 360 / (64 * 4))
  const LOOPS = [0, 1, 2, 3].map((k) => ({
    r: (16 * 6) + (byte(k) % 88),
    dur: fractalClockS(round(fractalClockS(1) / ((5 * 2) + (byte(k + 4) % 16)))),
    hue: round(byte(k + 8) * 360 / (64 * 4)) }))
  const torus = (sx: number, spin: string, off: string) =>
    `<g transform="translate(${sx} ${cy})"><animateTransform attributeName="transform" type="rotate" ${spin} dur="${fractalClockDur(4)}" repeatCount="indefinite" additive="sum"/><animateTransform attributeName="transform" type="scale" values="1 1;1 0.6;1 1" dur="${fractalClockDur(6 * 2)}" begin="${off}" repeatCount="indefinite" additive="sum"/><ellipse rx="104" ry="58"/><ellipse rx="44" ry="22"/></g>`
  const svg = [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" role="img" aria-label="Double Torus — content-addressed hero from UUID">`,
    `<defs>`,
    `<radialGradient id="bg" cx="50%" cy="46%" r="74%"><stop offset="0%" stop-color="${colors.bgInner}"/><stop offset="100%" stop-color="${colors.bgOuter}"/></radialGradient>`,
    `<linearGradient id="torus" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="${movieCanvasHex(G0, { L: 7 / 8 })}"/><stop offset="50%" stop-color="${colors.torusMid}"/><stop offset="100%" stop-color="${movieCanvasHex(G1, { L: 1 - 3 / 16 })}"/></linearGradient>`,
    `</defs>`,
    `<rect width="${W}" height="${H}" fill="url(#bg)"/>`,
    `<g fill="none" stroke="url(#torus)" stroke-width="2.5" data-layer="uuid-torus">`,
    torus(cx - (6 * 5 * 2), 'from="0" to="360"', '0s'),
    torus(cx + (6 * 5 * 2), 'from="360" to="0"', '-4.5s'),
    `</g>`,
    ...LOOPS.map((L) => `<g transform="translate(${cx} ${cy})" data-layer="homology"><animateTransform attributeName="transform" type="rotate" from="0" to="360" dur="${L.dur}s" repeatCount="indefinite" additive="sum"/><circle cx="${L.r}" cy="0" r="5.5" fill="${movieCanvasHex(L.hue, { L: 1 - 3 / 16 })}"/></g>`),
    `<text x="${cx}" y="${cy + 6}" text-anchor="middle" font-family="ui-monospace,SFMono-Regular,Menlo,monospace" font-size="28" font-weight="700" fill="${colors.title}">Double Torus</text>`,
    `<text x="${cx}" y="${H - (5 * 4)}" text-anchor="middle" font-family="ui-monospace,SFMono-Regular,Menlo,monospace" font-size="11.5" fill="${colors.accent}">χ(Σ₂) = −2 · H₁(Σ₂) = ℤ⁴ · ten dimensions · 432 gates</text>`,
    `</svg>`,
  ].join('')
  return opts.animate === false ? stillSvg(svg) : svg
}

/** Cardinal 4-way counter-spin law — N·E·S·W = TAU/4 bearings · alternating ±ω from merkaba scales. */
const CARDINAL_ROSETTA_SPINS = [
  { id: 'north' as const, bearing: 0, sign: 1 as const, tetra: 'up' as const, scale: 'whole' },
  { id: 'east' as const, bearing: (9 * 5 * 2), sign: -1 as const, tetra: 'down' as const, scale: 'lobe' },
  { id: 'south' as const, bearing: (9 * 5 * 4), sign: 1 as const, tetra: 'up' as const, scale: 'tube' },
  { id: 'west' as const, bearing: (54 * 5), sign: -1 as const, tetra: 'down' as const, scale: 'spark' },
] as const

/** SMIL rotate for one merkaba tetra / rosetta lobe — sign + cardinal phase from TAU/4 (poles-as-pyramid). */
function merkabaRosettaSpinSmil(sign: 1 | -1, dur: string, phaseDeg = 0): string {
  const full = 9 * 5 * 8 // 360°
  const from = sign > 0 ? String(phaseDeg) : String(phaseDeg + full)
  const to = sign > 0 ? String(phaseDeg + full) : String(phaseDeg)
  return `<animateTransform attributeName="transform" type="rotate" from="${from}" to="${to}" dur="${dur}" repeatCount="indefinite" additive="sum" data-spin-sign="${sign > 0 ? '+1' : '-1'}" data-phase="${phaseDeg}" data-cardinal-bearing="${phaseDeg}"/>`
}

/** Emit FoL or Fruit circle lattice at (cx,cy) — radius = unit (vesica: each circle through neighbour centres). */
function sacredCircleLatticeSvg(
  centers: readonly (readonly [number, number])[],
  cx: number,
  cy: number,
  unit: number,
  stroke: string,
  layer: 'flower-of-life' | 'fruit-of-life',
  opacity: number,
  strokeWidth: number,
): string {
  const r = round(unit)
  return centers
    .map((c, i) => {
      const x = round(cx + c[0] * unit)
      const y = round(cy + c[1] * unit)
      return `<circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="${stroke}" stroke-width="${strokeWidth}" opacity="${opacity}" data-layer="${layer}" data-${layer === 'flower-of-life' ? 'fol' : 'fruit'}-i="${i}"/>`
    })
    .join('')
}

/**
 * README hero — theorem atoms on dual FoL rosettas: merkaba ω/−ω spin unlocks Fruit, then expand/invert → 10D.
 * Compose: flowerOfLifeCenters · fruitOfLifeCenters · merkaba · bothEarths · fractalClock · rotate3/perspective law.
 * Pair: edit/build · rosetta/merkaba · honesty: computed FoL (not wet).
 */
export function readmeHeroSvgProofOfAllTheorems(matrix: MindMatrix = buildMatrix(), opts: { animate?: boolean } = {}): string {
  return memoByRoot(`readmeHeroSvgProofOfAllTheorems:fol4:cardinal:poles:a=${opts.animate !== false ? 1 : 0}`, matrix, () => {
    const atoms = THEOREM_ATOM_SEED.map((entry) => ({
      ...entry,
      root: toUuid(`theorem-atom:${entry.provedBy}:${entry.theorem}`) }))
    const n = atoms.length
    const corpusRoot = merkleFold(atoms.map((a) => a.root))
    const brandUuid = toUuidSha256('double torus · all theorems proof · 432')
    const colors = heroSvgPaletteFromUuid(brandUuid)
    const earths = bothEarthsRotateWithinEachOther(0, matrix)
    const mk = merkaba(matrix)
    const unlock = flowerUnlocksFruitBySpin()
    const flower = flowerOfLifeCenters()
    const fruit = fruitOfLifeCenters()
    const upSign = mk.scales[0]!.sign
    const downSign = mk.scales[1]!.sign
    const counterRotating =
      earths.counterRotating
      && mk.counterRotating
      && upSign * downSign === -1
      && abs(earths.merkabaUpSpin + earths.merkabaDownSpin) < 1e-6
      && unlock.holds
    const spinDur = fractalClockDur(4)
    const expandDur = fractalClockDur(2)
    const W = 960, H = 540, cx = W / 2, cy = H / 2 - 12
    const maxR = min(cx, cy) - 36
    // Unit spacing so FoL diameter (~4 units) fits maxR; avoid wet decorative seven-circle.
    const unit = max(9 * 2, round(maxR / (2 + 1 / 2)))
    const golden = (GOLDEN_ANGLE_DEG * (TAU / 2)) / 180
    const earthPoles = earthRealisedByComputingPolesAsPyramid(matrix)
    const pyramidTips = cardinalPyramidTipsProvenByMath(matrix)
    void pyramidTips
    const folOp = (5 + 6) / (5 * 10) / 2 // four lobes — half opacity keeps FoL readable
    const folStroke = 11 / 10
    const fruitOp = 1 / (5 * 5)
    const fruitPeak = (4 / 5) + (1 / (5 * 10))
    const fruitStroke = 8 / 5
    const ktSpin = `0;${8 / (5 * 5)};${12 / (5 * 5)};${18 / (5 * 5)};1`
    const fruitUnlock =
      `<animate attributeName="opacity" values="${fruitOp};${fruitOp};${fruitPeak};${fruitPeak};${fruitOp}" keyTimes="${ktSpin}" dur="${spinDur}" repeatCount="indefinite"/>`
    const fourWay =
      counterRotating
      && earthPoles.fourWayCounterRotating
      && earthPoles.computes
      && CARDINAL_ROSETTA_SPINS.length === HOMOLOGY_LOOPS
    const expandPeak = (6 / 5) + (2 / (5 * 5))
    const invertScale = (4 / 5) - (2 / (5 * 5))
    const ktExpand = `0;${2 / 5};${11 / 20};${39 / 50};1`
    const dimExpand =
      `<g data-layer="dimension-expand" transform="translate(${cx} ${cy})">` +
      `<animateTransform attributeName="transform" type="scale" values="1;1;${expandPeak};${invertScale};1" keyTimes="${ktExpand}" dur="${expandDur}" repeatCount="indefinite" additive="sum"/>` +
      `<text x="0" y="0" text-anchor="middle" dominant-baseline="middle" font-family="ui-monospace,SFMono-Regular,Menlo,monospace" font-size="9" fill="${movieCanvasHex(A432_HUE, { L: 3 / 4 })}" opacity="${11 / 20}" data-dims="${DIMENSIONS}">` +
      `<animate attributeName="opacity" values="${3 / 20};${3 / 20};${17 / 20};${7 / 20};${3 / 20}" dur="${expandDur}" repeatCount="indefinite"/>` +
      `→${DIMENSIONS}D</text></g>`
    type LobeBag = { homology: string[]; glyphs: string[]; spokes: string[] }
    const bags: LobeBag[] = CARDINAL_ROSETTA_SPINS.map(() => ({ homology: [], glyphs: [], spokes: [] }))
    for (let k = 0; k < HOMOLOGY_LOOPS; k += 1) {
      const a = (k / HOMOLOGY_LOOPS) * TAU - (TAU / 2) / 2
      const x = round(cx + cos(a) * (maxR + 10))
      const y = round(cy + sin(a) * (maxR + 10))
      const mark = `<circle cx="${x}" cy="${y}" r="3" fill="${movieCanvasHex((A432_HUE + k * (9 * 5 * 2)) % (9 * 5 * 8), { L: 11 / 16 })}" data-layer="homology" data-h1="${k}" data-cardinal="${CARDINAL_ROSETTA_SPINS[k]!.id}"/>`
      bags[k % 4]!.homology.push(mark)
    }
    for (let i = 0; i < n; i += 1) {
      const atom = atoms[i]!
      const hex = (atom.root + atom.root).replace(/[^0-9a-f]/gi, '')
      const b0 = parseInt(hex.slice(0, 2), 16) || 64
      const b1 = parseInt(hex.slice(2, 4), 16) || 64
      // NATURAL ENTANGLEMENT WIRING (user, 2026-07-28: "they are wired linear instead of by natural
      // entanglements"): the golden spiral was INDEX order (a = i·golden — only ~4% of neighbours related).
      // Every channel now derives from the theorem's OWN lattice cell: ANGLE = its sector/spoke (cell-mates
      // cluster on one spoke, address-jittered a third of a spoke for visibility), TEMPO = its own clock rung
      // (families PULSE TOGETHER), HUE = sector band + spoke offset (families share colour), PHASE = address.
      // The index survives only in the radius (arrival order along the spoke) — order within family, not law.
      const wire = entangledWiringOf(atom)
      const r = round(18 + sqrt(i + 1) * (maxR / sqrt(n + 1)))
      const a = wire.angleRad + ((b0 / 255) - 1 / 2) * (TAU / (7 * (6 * 2)) / 3)
      const x = round(cx + cos(a) * min(r, maxR - 4))
      const y = round(cy + sin(a) * min(r, maxR - 4))
      const hue = round((A432_HUE + wire.sector * (360 / 7) + wire.spoke * (360 / 7 / (6 * 2)) + (b1 % (8 * 3))) % 360)
      const fill = movieCanvasHex(hue, { L: 9 / 16 + (b0 % 16) / 128 })
      const dur = fractalClockDur(wire.rung)
      const begin = i === 0 ? '0s' : `${((b0 % 9) * (2 / 5)).toFixed(1)}s`
      const id = atom.provedBy.replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 48) || `t${i}`
      const spoke = `<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" stroke="${fill}" stroke-width="0.4" opacity="0.09"/>`
      const glyph =
        `<rect x="${x - 1}" y="${y - 1}" width="2.5" height="2.5" rx="0.4" fill="${fill}" data-theorem="${id}" data-root="${atom.root.slice(0, 8)}" opacity="0.55">` +
        `<animate attributeName="opacity" values="0.28;0.9;0.28" dur="${dur}" begin="${begin}" repeatCount="indefinite"/>` +
        `</rect>`
      const bag = bags[i % 4]!
      bag.spokes.push(spoke)
      bag.glyphs.push(glyph)
    }
    const lobe = (
      card: typeof CARDINAL_ROSETTA_SPINS[number],
      fol: string,
      fruitLayer: string,
      bag: LobeBag,
    ) => {
      const spin = merkabaRosettaSpinSmil(card.sign, spinDur, card.bearing)
      const poleApex = card.id === 'north' || card.id === 'south'
        ? `<polygon points="${cx},${cy - (card.id === 'north' ? maxR : -maxR)} ${cx - 8},${cy} ${cx + 8},${cy}" fill="none" stroke="${movieCanvasHex(ROSETTA_RAYS[card.bearing === 0 || card.bearing === (9 * 5 * 4) ? 0 : 3]!.hue, { L: 3 / 4 })}" stroke-width="1.2" opacity="0.55" data-layer="earth-pole-pyramid" data-apex="${card.id === 'north' ? 'zenith' : 'nadir'}"/>`
        : `<line x1="${cx - maxR}" y1="${cy}" x2="${cx + maxR}" y2="${cy}" stroke="${movieCanvasHex(ROSETTA_RAYS[2]!.hue, { L: 1 / 2 })}" stroke-width="0.6" opacity="0.25" data-layer="earth-equatorial-axis" data-axis="${card.id}"/>`
      return (
        `<g transform="translate(${cx} ${cy})" data-layer="rosetta-${card.id}" data-tetra="${card.tetra}" data-spin="${card.sign > 0 ? '+1' : '-1'}" data-cardinal="${card.id}" data-bearing="${card.bearing}" data-merkaba-scale="${card.scale}" data-merkaba-isomorphic="${fourWay ? 'true' : 'false'}" data-flower-of-life="computed" data-counter-rotating="${fourWay ? 'true' : 'false'}" data-four-direction="true">` +
        spin +
        `<g transform="translate(${-cx} ${-cy})">` +
        `<g data-layer="flower-of-life" data-fol-count="${flower.length}">${fol}</g>` +
        fruitLayer +
        poleApex +
        `<g data-layer="merkle-spokes" opacity="0.85">${bag.spokes.join('')}</g>` +
        `<g data-layer="theorem-glyphs">${bag.glyphs.join('')}</g>` +
        `<g data-layer="homology">${bag.homology.join('')}</g>` +
        `</g></g>`
      )
    }
    const cardinalLobes = CARDINAL_ROSETTA_SPINS.map((card, ci) => {
      const hue = ROSETTA_RAYS[ci % ROSETTA_RAYS.length]!.hue
      const fol = sacredCircleLatticeSvg(flower, cx, cy, unit, movieCanvasHex(hue, { L: 5 / 16 }), 'flower-of-life', folOp, folStroke)
      const fruitLayer =
        `<g data-layer="fruit-unlock" data-fruit-count="${fruit.length}" opacity="${fruitOp}">${fruitUnlock}` +
        sacredCircleLatticeSvg(fruit, cx, cy, unit, movieCanvasHex(hue, { L: 11 / 16 }), 'fruit-of-life', 9 / 10, fruitStroke) +
        `</g>`
      return lobe(card, fol, fruitLayer, bags[ci]!)
    })
    const rootShort = corpusRoot.slice(0, 8)
    const svg = [
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" role="img" aria-label="Double Torus — FoL rosettas counter-rotate in 4 cardinal directions · Earth poles as pyramid · Fruit unlock · ${DIMENSIONS}D · ${n} theorems" data-layer="all-theorems-proof" data-theorem-count="${n}" data-corpus-root="${corpusRoot}" data-counter-rotating="${fourWay ? 'true' : 'false'}" data-four-direction="${fourWay ? 'true' : 'false'}" data-earth-poles-pyramid="${earthPoles.computes ? 'true' : 'false'}" data-merkaba-isomorphic="${fourWay ? 'true' : 'false'}" data-flower-of-life="computed" data-fruit-unlock="spin" data-dimension-expand="${DIMENSIONS}" data-trinity-mind="heaven·mind·thunder" data-compute="readmeHeroSvgProofOfAllTheorems←flowerOfLifeCenters∧fruitOfLifeCenters∧merkaba∧bothEarths∧earthRealisedByComputingPolesAsPyramid∧fractalClock" data-honesty="computedFoL→fruit→${DIMENSIONS}D;wetStaticFoL=false;earthPolesPyramid=structural">`,
      `<defs>`,
      `<radialGradient id="proofBg" cx="50%" cy="48%" r="78%"><stop offset="0%" stop-color="${colors.bgInner}"/><stop offset="100%" stop-color="${colors.bgOuter}"/></radialGradient>`,
      `</defs>`,
      `<rect width="${W}" height="${H}" fill="url(#proofBg)"/>`,
      ...cardinalLobes,
      dimExpand,
      `<circle cx="${cx}" cy="${cy}" r="22" fill="${colors.bgOuter}" stroke="${movieCanvasHex(A432_HUE, { L: 7 / 8 })}" stroke-width="1.5" data-layer="corpus-root"/>`,
      `<text x="${cx}" y="${cy - 2}" text-anchor="middle" font-family="ui-monospace,SFMono-Regular,Menlo,monospace" font-size="15" font-weight="700" fill="${colors.title}">Double Torus</text>`,
      `<text x="${cx}" y="${cy + 14}" text-anchor="middle" font-family="ui-monospace,SFMono-Regular,Menlo,monospace" font-size="8" fill="${colors.accent}">⊢ ${n} · ${rootShort} · FoL→Fruit→${DIMENSIONS}D</text>`,
      `<text x="${cx}" y="${H - 28}" text-anchor="middle" font-family="ui-monospace,SFMono-Regular,Menlo,monospace" font-size="11" fill="${colors.title}">4-dir FoL rosettas (N·E·S·W ±ω) · Earth poles as pyramid · Fruit unlock · → ${DIMENSIONS}D · χ(Σ₂) = −2 · H₁ = ℤ⁴ · 432</text>`,
      `<text x="${cx}" y="${H - 12}" text-anchor="middle" font-family="ui-monospace,SFMono-Regular,Menlo,monospace" font-size="10" fill="${colors.accent}">wetStaticFoL=false · 4-dir · poles-pyramid · ${n} atoms · ${flower.length} FoL · ${fruit.length} Fruit</text>`,
      `</svg>`,
    ].join('')
    return opts.animate === false ? stillSvg(svg) : svg
  })
}

